def find_solution(a, b, n):
    from math import gcd

    if a == 0 and b == 0:
        return 'No solution' if n != 0 else (0, 0)

    g = gcd(a, b)
    if n % g != 0:
        return 'No solution'

    # Extended Euclidean Algorithm to find one solution of ax + by = gcd(a,b)
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        g, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)
    x0 *= n // g
    y0 *= n // g

    # a and b divided by gcd
    a_div = a // g
    b_div = b // g

    # Now find t such that x = x0 + t*b_div >= 0 and y = y0 - t*a_div >= 0
    # Inequalities:
    # x0 + t*b_div >= 0  => t >= -x0 / b_div
    # y0 - t*a_div >= 0  => t <= y0 / a_div

    # Because a, b, n can be any integers, but we want non-negative integer solutions,
    # we find integer t in the intersection of these inequalities.

    # Note: If b_div == 0, then x = x0 constant, must be >= 0,
    # similarly if a_div == 0, y = y0 constant, must be >= 0.

    # Handle zero division carefully:
    t_min = float('-inf')
    t_max = float('inf')

    if b_div != 0:
        t_min = (-x0 + (b_div - 1)) // b_div if b_div > 0 else (-x0) // b_div  # ceil division of -x0/b_div
        # The formula above ensures t_min is the smallest integer t with x >= 0

    else:
        if x0 < 0:
            return 'No solution'

    if a_div != 0:
        # floor division of y0 / a_div
        t_max = y0 // a_div if a_div > 0 else (y0 + (-a_div) - 1) // a_div

    else:
        if y0 < 0:
            return 'No solution'

    if t_min > t_max:
        return 'No solution'

    # Choose any t in [t_min, t_max], for simplicity take t = t_min
    t = t_min
    x = x0 + t * b_div
    y = y0 - t * a_div

    if x < 0 or y < 0:
        return 'No solution'

    return (x, y)

