def get_total_number_of_sequences(n, m):
    # dp[i][x] = number of sequences of length i ending with x
    # We want sum of dp[n][x] for x in [1..m]
    if n == 1:
        return m  # sequences of length 1: any number from 1 to m

    dp_prev = [1] * (m + 1)  # for length 1, count=1 for each x in [1..m], dp_prev[0] unused
    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        # prefix sums of dp_prev for quick range sums
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp_prev[x]
        # For each x, next element must be >= 2*x
        for x in range(1, m + 1):
            start = 2 * x
            if start <= m:
                dp_curr[start] += dp_prev[x]  # Actually we need sum over all next elements >= 2*x,
                # but we should sum dp_prev[x] for previous element and next element >= 2*x
                # Wait, correction: dp_curr[x] depends on dp_prev[y] where y <= m and next element is x,
                # and x >= 2*y. So to compute dp_curr[x], sum dp_prev[y] for y in [1..x//2].
                # So the above is reversed. We need to rethink.

        # Reconsider approach:
        # dp[i][x] = sum over y where x >= 2*y of dp[i-1][y]
        # For fixed x, the previous element y must satisfy y <= x//2
        # So dp_curr[x] = sum of dp_prev[y] for y in [1..x//2]

        for x in range(1, m + 1):
            max_prev = x // 2
            if max_prev >= 1:
                dp_curr[x] = prefix[max_prev]
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr

    return sum(dp_prev[1:])

