def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # If num is less than 9, next palindrome is num+1
    if num < 9:
        return num + 1

    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    # If all digits are 9, next palindrome is 10...01 with length+1 digits
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Helper to create palindrome by mirroring left half to right half
    def make_palindrome(left, length):
        if length % 2 == 0:
            return int(left + left[::-1])
        else:
            return int(left + left[-2::-1])

    # Increment a numeric string by 1 and return as string
    def increment_str(num_str):
        num_list = list(num_str)
        i = len(num_list) - 1
        while i >= 0:
            if num_list[i] == '9':
                num_list[i] = '0'
                i -= 1
            else:
                num_list[i] = str(int(num_list[i]) + 1)
                break
        else:
            # All 9's case handled before, but just in case:
            num_list.insert(0, '1')
        return ''.join(num_list)

    # Generate a palindrome candidate
    mid = (length + 1) // 2
    left = s[:mid]
    palindrome = make_palindrome(left, length)

    if palindrome > num:
        return palindrome

    # Else increment left half and then mirror again
    left_inc = increment_str(left)
    # If incrementing left increases length (e.g. 999 -> 1000)
    # then palindrome length increases by 1 (e.g. 999 -> 10001)
    if len(left_inc) > len(left):
        # For length even, new palindrome length is length+1 (odd)
        # For length odd, new palindrome length is length+1 (even)
        if length % 2 == 0:
            # length even, new length odd
            palindrome = int(left_inc + left_inc[-2::-1])
        else:
            # length odd, new length even
            palindrome = int(left_inc + left_inc[::-1])
    else:
        palindrome = make_palindrome(left_inc, length)

    return palindrome

