    """
    Compute the minimum number of bit flips needed to make the binary string `s`
    strictly alternate, considering both possible starting bits (0 or 1).
    Returns the smaller of the two costs.
    """
    flips_start_with_0 = 0
    flips_start_with_1 = 0

    for i, char in enumerate(s):
        expected_bit_0 = '0' if i % 2 == 0 else '1'
        expected_bit_1 = '1' if i % 2 == 0 else '0'

        if char != expected_bit_0:
