    if start == end:
        return arr[start]
    if arr[start] < arr[end]:
        return arr[end]

    mid = (start + end) // 2

    # Check if mid element is greater than next element
    if mid < end and arr[mid] > arr[mid + 1]:
        return arr[mid]
    # Check if mid element is smaller than previous element
    if mid > start and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    # Decide which half to choose for the maximum
