def find_Max(arr):
    if not arr:
        return None
    left, right = 0, len(arr) - 1
    # If array is not rotated (sorted ascending), max is last element
    if arr[left] < arr[right]:
        return arr[right]
    while left < right:
        mid = (left + right) // 2
        if arr[mid] > arr[right]:
            left = mid + 1
        else:
            right = mid
    # left now points to the minimum element
    # max element is element before minimum, considering wrap-around
    return arr[left - 1]

