def compute_Last_Digit(A: int, B: int) -> int:
    # If A == B, product is empty -> by convention return 1 (neutral element of multiplication)
    if A == B:
        return 1
    # If B < A, no product range -> return 1 as well (or could raise, but choose 1)
    if B < A:
        return 1
    # If difference is at least 5, product contains a multiple of 10 => last digit 0
    if B - A >= 5:
        return 0
    # Otherwise, calculate product of integers from A+1 to B and return last digit
    product = 1
    for x in range(A + 1, B + 1):
        product *= x
    return product % 10

