def find_solution(a, b, n):
    # Extended Euclidean Algorithm to find gcd and coefficients x, y such that a*x + b*y = gcd(a,b)
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        gcd, x1, y1 = extended_gcd(y, x % y)
        return gcd, y1, x1 - (x // y) * y1

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % gcd != 0:
        return None  # No integer solutions

    # Scale the solution to n
    x0 *= n // gcd
    y0 *= n // gcd

    # Adjust sign if a or b was negative
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    return x0, y0

