def move_num(data):
    """
    Extract all numeric values from the input (string, list, or nested structures)
    and return them concatenated as a single string.

    If input is a string, extract digits from it.
    If input is a list or tuple, extract numeric values from it recursively.
    For other types, convert numeric values to string if possible.

    Args:
        data: input data containing values to extract numbers from.

    Returns:
        A string containing all numeric values concatenated in order.
    """
    def extract_numbers(x):
        if isinstance(x, str):
            # Extract digits from string
            return ''.join(ch for ch in x if ch.isdigit())
        elif isinstance(x, (list, tuple)):
            # Recursively extract from elements
            return ''.join(extract_numbers(e) for e in x)
        elif isinstance(x, (int, float)):
            # Convert numbers to string (remove decimal if float is integral)
            if isinstance(x, float) and x.is_integer():
                return str(int(x))
            return str(x)
        else:
            # Ignore other types
            return ''

    return extract_numbers(data)

