def find_solution(a, b, n):
    # We want to find integers x,y such that a*x + b*y = n,
    # with x >= 0 and minimal.
    # If no solution, return None.

    # Handle trivial cases:
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        # b*y = n => y = n/b if integer
        if b != 0 and n % b == 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        # a*x = n => x = n/a if integer and x >= 0
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # Use Extended Euclidean Algorithm to solve a*x + b*y = gcd(a,b)
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return (gcd, x, y)

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % gcd != 0:
        return None

    # scale the solution to n
    x0 *= n // gcd
    y0 *= n // gcd

    # adjust sign for a,b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # general solution:
    # x = x0 + k*(b/gcd)
    # y = y0 - k*(a/gcd)
    # we want smallest x >= 0

    b_div = b // gcd
    a_div = a // gcd

    # find k to get x >= 0
    # x0 + k*b_div >= 0  => k >= -x0 / b_div
    # k can be positive or negative depending on b_div

    if b_div == 0:
        # then x = x0 fixed, check if x0 >= 0
        if x0 >= 0:
            return (x0, y0)
        else:
            return None

    # k_min is the smallest integer k such that x >= 0
    # careful with integer division and sign of b_div
    if b_div > 0:
        k_min = (-x0 + b_div - 1) // b_div  # ceil(-x0/b_div)
    else:
        k_min = (-x0) // b_div  # floor(-x0/b_div) because b_div < 0

    x = x0 + k_min * b_div
    y = y0 - k_min * a_div

    if x < 0:
        return None
    else:
        return (x, y)

