def remove_column(collection, index):
    def process(obj):
        if isinstance(obj, list):
            # Process inner lists recursively
            # If the list contains only non-list elements, remove index if possible
            if all(not isinstance(el, list) for el in obj):
                if 0 <= index < len(obj):
                    return obj[:index] + obj[index+1:]
                else:
                    return obj[:]
            else:
                # For lists that contain inner lists, process each element recursively
                return [process(el) for el in obj]
        else:
            # For non-list elements, return as is
            return obj

    return process(collection)

