def find_Max(nums):
    if not nums:
        return None
    left, right = 0, len(nums) - 1
    # If the list is not rotated (sorted ascending), the last element is max
    if nums[left] < nums[right]:
        return nums[right]
    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than the rightmost, max is in right half
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    # After loop, left points to the smallest element
    # max is element before smallest (or last if smallest is first)
    return nums[left - 1] if left > 0 else nums[-1]

