def prime_length(string):
    length = len(string)
    if length < 2:
        return False
    for i in range(2, int(length**0.5) + 1):
        if length % i == 0:
            return False
    return True

def sum_squares(lst):
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total

def order_by_points(nums):
    def digit_sum(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n >= 0:
            return sum(digits)
        else:
            # subtract first digit, add rest
            return -digits[0] + sum(digits[1:])
    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def solve(s):
    if any(c.isalpha() for c in s):
        return s.swapcase()
    else:
        return s[::-1]
